def longest_common_subsequence(a, b):
    def f(i, j):               # LCS of a[:i] and b[:j]
        if i == 0 or j == 0:
            return 0
        if a[i - 1] == b[j - 1]:
            return 1 + f(i - 1, j - 1)
        return max(f(i - 1, j), f(i, j - 1))
    return f(len(a), len(b))

