def longest_common_subsequence(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

def longest_common_subsequence(a, b):
    n = len(b)
    prev = [0] * (n + 1)
    for ch in a:
        cur = [0] * (n + 1)
        for j in range(1, n + 1):
            if ch == b[j - 1]:
                cur[j] = 1 + prev[j - 1]
            else:
                cur[j] = max(prev[j], cur[j - 1])
        prev = cur
    return prev[n]

def longest_common_subsequence(a, b):
    if len(b) > len(a):
        a, b = b, a
    row = [0] * (len(b) + 1)
    for ch in a:
        diag = 0                     # dp[i-1][j-1]
        for j in range(1, len(b) + 1):
            above = row[j]
            row[j] = diag + 1 if ch == b[j - 1] else max(above, row[j - 1])
            diag = above
    return row[-1]
